    private FrameLayout contentRoot; private WebView webView; private String pendingPhotoRole="item"; private FacebookMarketplaceEmbeddedCollector facebookCollector;
    @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(Color.rgb(13,42,62));getWindow().setNavigationBarColor(Color.WHITE);contentRoot=new FrameLayout(this);contentRoot.setBackgroundColor(Color.rgb(243,246,248));webView=new WebView(this);webView.setBackgroundColor(Color.rgb(243,246,248));contentRoot.addView(webView,new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.MATCH_PARENT));setContentView(contentRoot);applyInsets();WebSettings settings=webView.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setDatabaseEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setMediaPlaybackRequiresUserGesture(true);settings.setUserAgentString(settings.getUserAgentString()+" H38ResellerScoutAndroid/"+BuildConfig.VERSION_NAME);NativeBridge bridge=new NativeBridge();webView.addJavascriptInterface(bridge,"AndroidH38Reseller");webView.addJavascriptInterface(bridge,"AndroidH38Scout");webView.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,String url){if(url==null)return false;if(url.startsWith(APP_BASE_URL))return false;if(url.startsWith("http://")||url.startsWith("https://")){openExternal(url);return true;}return false;}@Override public void onPageFinished(WebView view,String url){deliverSharedText(getIntent());}});webView.loadDataWithBaseURL(APP_BASE_URL,bundledPage(),"text/html","UTF-8",null);}
    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);deliverSharedText(intent);}
